@functools.lru_cache(maxsize=None)
def _decode(name):
    return cv2.imdecode(np.frombuffer(base64.b64decode(TEMPLATES[name]), np.uint8), cv2.IMREAD_COLOR)


def tpl(name):
    return _decode(name).copy()


def digit_templates():
    for d, b in DIGITS:
        yield d, cv2.imdecode(np.frombuffer(base64.b64decode(b), np.uint8), cv2.IMREAD_GRAYSCALE)
